import json,glob,os
seen={}
for f in sorted(glob.glob('pack*/*.jsonl'))+sorted(glob.glob('rt/*.jsonl')):
    for l in open(f):
        try: d=json.loads(l)
        except: continue
        if d.get('clight') and float(d['clight'])>1e5:
            Z=d['Z']; seen.setdefault(Z,[]).append((os.path.basename(f),d.get('ent'),d.get('margin')))
print('ALL ROWS EVER RUN AT c=1e6, read from the archive:')
for Z in sorted(seen):
    print(f'  Z={Z:3d}  ', '; '.join(f'{a}:{b}/{c}' for a,b,c in seen[Z]))
print()
print('count of distinct Z at c=1e6 :', len(seen))
print('the set                      :', sorted(seen))
"

